import React, { useState } from "react";
import JobStats from "../components/JobStats";
import JobTable from "../components/JobTable";
import JobForm from "../components/JobForm";

const JobAdminPage = () => {
  const [showForm, setShowForm] = useState(false);
  const [jobs, setJobs] = useState([]);

  const handleAddJob = (job) => {
    setJobs([...jobs, job]);
    setShowForm(false);
  };

  const handleDeleteJob = (index) => {
    const updated = jobs.filter((_, i) => i !== index);
    setJobs(updated);
  };

  return (
    <>
      {/* Header */}
      <div className="header-card">
        <div className="header-left">
          <h1>Careers Dashboard</h1>
          <p>Manage job openings and performance insights</p>
        </div>
        <button className="add-btn" onClick={() => setShowForm(true)}>
          + Add Job
        </button>
      </div>

      {/* Stats */}
      <JobStats jobs={jobs} />

      {/* Table */}
      <div className="table-container">
        <JobTable jobs={jobs} onDelete={handleDeleteJob} />
      </div>

      {/* Modal Form */}
      {showForm && <JobForm onSave={handleAddJob} onCancel={() => setShowForm(false)} />}
    </>
  );
};

export default JobAdminPage;
